import java.util.Scanner;

public class Main {
    public static int countDigits(long n) {
        int digits = 0;
        while (n > 0) {
            n /= 10;
            digits++;
        }
        return digits;
    }

    public static long getLargestOnes(long n) {
        int length = countDigits(n);
        long sum = 0, power = 1;
        for (int i = 0; i < length; i++) {
            sum += power;
            power *= 10;
        }
        if (sum <= n) return sum;
        return (sum - 1) / 10;
    }

    public static long solve(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base = getLargestOnes(n);
        long nextVal = base * 10 + 1;
        if (n % base == 0) {
            if (n <= (nextVal / 2 + base))
                return countDigits(base) * n / base;
            return countDigits(nextVal) + solve(nextVal - n);
        } else {
            long m = (n / base) * base;
            long result = solve(m) + solve(n - m);
            if (n > nextVal / 2)
                result = Math.min(solve(m) + solve(n - m), countDigits(nextVal) + solve(nextVal - n));
            return result;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(solve(n));
        scanner.close();
    }
